# PERCEPT preprocessing pipeline part 1 functions


# part 1_1

# Read in the 10X raw data. Specifically, we need to specify a data directory (usually named "filtered_feature_bc_matrix") that contains the triplets files generated by CellRanger:
# - barcodes.tsv: contains cell barcodes (names to each cell, similar as sample/cell name)
# - features.tsv: contains gene (n=36601) and antibody (n=8/9/33) names
# - matrix.mtx: contains the actual count matrix (cell*features)

# Inputs:
# Sample_name: Sample name (e.g. YUEYE)
# input_data_dir: directory path containing input data (triplets files generated by CellRanger)
# output_all_cells: file path for saving all cell seurat object as rds file

create_Seurat_RDS_from_10X_sample <- function(Sample_name, input_data_dir, output_all_cells){
  
  # read the data
  Sample.data <- Read10X(data.dir = input_data_dir)
  
  # separate and store scRNA data
  Sample_RNA <- CreateSeuratObject(counts = Sample.data[[1]], project=Sample_name,assay="RNA")
  
  # separate and store the Antibody data (includes cell hashing results and CITEseq)
  Sample_antibody <- CreateSeuratObject(counts=Sample.data[[2]],project=Sample_name,assay="Antibody")
  
  # remove objects (especially objects large in size) that we are not using later in order to free up spaces
  rm(Sample.data)
  
  # Get the RNA and Antibody count matrices and make sure they have the same columns names
  count_matrix_Sample_rna <- GetAssayData(Sample_RNA,slot="counts")
  count_matrix_Sample_antibody <-GetAssayData(Sample_antibody,slot="counts")
  joint_Sample.bcs <- intersect(colnames(count_matrix_Sample_rna),colnames(count_matrix_Sample_antibody))
  count_matrix_Sample_rna <- count_matrix_Sample_rna[,joint_Sample.bcs]
  count_matrix_Sample_antibody <- count_matrix_Sample_antibody[,joint_Sample.bcs]
  
  rm(Sample_RNA)
  rm(Sample_antibody)
  rm(joint_Sample.bcs)
  
  
  # Create and normalize the Seurat object that we are using for later processing.
  
  # use the column matched count matrix to set up RNA assay 
  Sample <- CreateSeuratObject(counts=count_matrix_Sample_rna, assay="RNA")
  
  #Normalize the RNA data
  # default: log normalization that normalizes the feature expression measurements for each cell by the total expression,
  # multiplies this by a scale factor (10,000), and log-transform the result
  Sample <- NormalizeData(Sample, assay = "RNA", normalization.method = "LogNormalize")
  
  #Find and scale variable features
  # select a subset of features that exhibit high cell-to-cell variation
  # default: return 2000 features per dataset
  Sample <- FindVariableFeatures(Sample,selection.method="vst")
  # scaling: linear transformation (standardization), mean = 0, variance = 1
  Sample <- ScaleData(Sample, features=VariableFeatures(Sample))
  
  
  # add the antibody/hashtags data as a new assay independent from RNA
  Sample[["HTO"]] <- CreateAssayObject(counts=count_matrix_Sample_antibody)
  
  #Normalize HTO data, here we are using centered log-ratio (CLR) transformation
  Sample <- NormalizeData(Sample,assay="HTO", normalization.method="CLR")
  
  rm(count_matrix_Sample_rna)
  rm(count_matrix_Sample_antibody)
  
  
  # HTO demultiplexing: classify single cells to their sample of origins
  # Though there are usually many experimental conditions, scRNA seq was done by having all the cells sequenced all together. So we need to add HTO to different conditions to help us identify which condition each cell was from. We sequenced the HTO hashtags through CITE-seq.
  # Since PERCEPT has 8 experimental conditions, there are 8 different HTO hashtags that represent 8 different conditions.
  
  
  # Output: Seurat object with demultiplexed information stored in the meta data
  Sample <- HTODemux(Sample,assay="HTO",kfunc="clara",positive.quantile=0.99,verbose=TRUE)
  
  #Visualize number of cells per classification (singlets, doublets, negative)
  #table(Sample$HTO_classification.global)
  DefaultAssay(Sample) <- "HTO"
  Idents(Sample) <- "HTO_classification"
  
  
  # This is to save the current Seurat object as RDS file so you don't need to run the above process again.
  # You can load any RDS files by "data_name <- readRDS(file_path)"
  saveRDS(Sample,file=output_all_cells)
  
}


# part 1_3

# Custom doublet detection function based on DoubletFinder package - to be run right after filtering away poor quality cells ----
# Beware that part of the function is assuming the doublet formation rate. This may need some adjustment.
# Relies on DoubletFinder and Seurat packages
# NB: Slow function with a lot of printed things including a plot.
# Inputs:
#    seurat: Seurat object
# Output: Seurat object

DoubletFinder_custom <- function(seurat) {
  require(Seurat); require(DoubletFinder)
  ## Pre-process Seurat object (standard)
  seurat <- NormalizeData(seurat, verbose = F) %>%
    FindVariableFeatures(selection.method = "vst", nfeatures = 2000, verbose = F) %>%
    ScaleData(verbose = F) %>%
    RunPCA(verbose = F) %>%
    RunUMAP(dims = 1:10, verbose = F) %>%
    FindNeighbors(dims = 1:10, verbose = F) %>%
    FindClusters(resolution = 0.5, verbose = F)
  
  ## pK Identification
  sweep.res.list <- paramSweep(seurat, PCs = 1:10, sct = FALSE)
  sweep.stats <- summarizeSweep(sweep.res.list, GT = FALSE)
  
  #pdf(file="/home/wt284/Desktop/Tumor_Integration/MCC-YURAD/QC_Plots/standard_Miya.pdf")
  bcmvn <- find.pK(sweep.stats)
  while (!is.null(dev.list())) dev.off()
  
  # calculate the doublet formation rate, based on Doublet Formation linear regression
  # slope: 1317.451, intercept: 68.65
  # https://pubmed.ncbi.nlm.nih.gov/30954475/
  rate = (ncol(seurat)+68.65)/1317.451/100
  
  ## Homotypic Doublet Proportion Estimate
  homotypic.prop <- modelHomotypic(seurat$seurat_clusters)
  nExp_poi <- round(rate*nrow(seurat@meta.data))  ## Assuming 7.5% doublet formation rate - may not be a good estimate (5.2%)
  nExp_poi.adj <- round(nExp_poi*(1-homotypic.prop))
  
  ## Run DoubletFinder with homotypic
  seurat <- doubletFinder(seurat, PCs = 1:10, pN = 0.25, pK = as.numeric(as.character(bcmvn[which.max(bcmvn$BCmetric), 'pK'])), nExp = nExp_poi, reuse.pANN = FALSE, sct = FALSE)
  
  ## Return singlet/doublet labels
  
  return(seurat[[names(seurat@meta.data)[length(seurat@meta.data)]]])
  
}


# define the function to add the condition label based on the corresponding hashtag
match_hashtag_to_condition <- function(row, seurat_obj) {
  hashtag <- toString(row[[1]])
  condition <- toString(row[[2]])
  
  Idents(seurat_obj) <- seurat_obj@meta.data$HTO_classification
  HTO_subset <- subset(seurat_obj, idents=hashtag)
  seurat_obj$condition[Cells(HTO_subset)] <- paste(condition)
  
  return(seurat_obj)
}






